import {localCheck,levelFor} from './link-lens.js';
const $=s=>document.querySelector(s);const form=$('#check-form'),url=$('#url'),result=$('#result'),error=$('#error');
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
function card(score,level,summary){const n=document.createElement('section');n.className='risk-card '+level;n.innerHTML='<p class="risk-kicker">RISK SIGNAL</p><strong class="risk-number">'+score+'</strong><span class="risk-out-of">/ 100</span><p class="risk-name">'+(level==='high'?'High':level==='review'?'Caution':'Low')+'</p><div class="risk-bar"><div class="risk-fill" style="width:'+score+'%"></div></div><p class="risk-summary"></p>';n.querySelector('.risk-summary').textContent=summary;return n;}
function liveButton(data){const actions=el('div',undefined,'result-actions'),button=el('button','Check live reputation','quiet');button.type='button';button.addEventListener('click',()=>runLive(data,button));actions.append(button);return actions;}
function renderLocal(data){const level=levelFor(data.score);result.replaceChildren(card(data.score,level,'Link Lens checked the address structure on this device. The link was not opened.'));result.append(el('div',level==='high'?'Do not click. Verify through a trusted website or phone number.':level==='review'?'Pause and verify using an address you find yourself.':'Few structural warnings found. This does not prove the link is safe.','result-banner '+level),el('p','Address: '+data.host,'link-host'));if(data.signals.length){const list=el('ul',undefined,'findings');data.signals.forEach(s=>{const item=el('li');item.append(el('strong',s.text),el('p','Adds '+s.points+' points to the local risk signal.','reason'));list.append(item);});result.append(list);}else result.append(el('p','No structural warning signs were found in this address. Keep verifying unexpected messages through a trusted source.','model-note'));const box=el('div',undefined,'next-step');box.innerHTML='<h3>What to do now</h3><ol><li>Do not enter a password from an unexpected link.</li><li>Type the official address yourself or use a bookmark.</li><li>Contact the sender through a trusted channel.</li></ol><p class="model-note">Optional live reputation sends only this link to Google Web Risk through the VerifyBridge API.</p>';box.append(liveButton(data));result.append(box);result.focus({preventScroll:true});result.scrollIntoView({behavior:'smooth',block:'start'});}
async function runLive(data,button){button.disabled=true;button.textContent='Checking live reputation…';error.textContent='';try{const response=await fetch('/api/scan',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({url:data.value})});const raw=await response.text();let scan=null;try{scan=JSON.parse(raw);}catch{}if(!response.ok||!scan)throw Error(scan?.error||'Live scan is temporarily unavailable.');const liveScore=Math.min(100,data.score+(scan.unsafe?35:0)),level=levelFor(liveScore),outcome=scan.unsafe?'Live reputation check found: '+scan.threat.join(', ').replaceAll('_',' ').toLowerCase()+'. Do not open this link.':'Live reputation check found no known malware or phishing match. This is not a guarantee that the link is safe.';result.replaceChildren(card(liveScore,level,outcome));result.append(el('div',outcome,'result-banner '+level),el('p','Address: '+data.host,'link-host'));const next=el('div',undefined,'next-step');next.innerHTML='<h3>What to do now</h3><ol><li>Never enter a password from an unexpected link.</li><li>Type the official address yourself.</li><li>Contact the sender through a trusted channel.</li></ol>';result.append(next);}catch(e){button.disabled=false;button.textContent='Try live check again';error.textContent=e.message+' You can still use the local Link Lens result.';} }
form.addEventListener('submit',event=>{if(!document.querySelector('[data-mode="link"]')?.classList.contains('active'))return;event.preventDefault();event.stopImmediatePropagation();error.textContent='';try{renderLocal(localCheck(url.value));}catch(e){error.textContent=e.message;}},true);
const privacy=$('.link-privacy');if(privacy)privacy.textContent='Link Lens checks the address on this device and never opens the link.';
const footer=document.querySelector('footer [data-i="limit"]');if(footer)footer.textContent='A screening tool, not a verdict. Link Lens checks address patterns locally; an optional live check sends only the link to Google Web Risk.';
